import React from 'react';
import Svg, { Circle } from 'react-native-svg';
import { View } from 'react-native';

function Ring({ pct, r, color, stroke = 14 }) {
  const c = 2 * Math.PI * r;
  return (
    <>
      <Circle cx="100" cy="100" r={r} stroke={color + '33'} strokeWidth={stroke} fill="none" />
      <Circle cx="100" cy="100" r={r} stroke={color} strokeWidth={stroke} fill="none"
        strokeDasharray={`${c} ${c}`} strokeDashoffset={c * (1 - pct / 100)}
        strokeLinecap="round" transform="rotate(-90 100 100)" />
    </>
  );
}

export default function {{component_name}}() {
  return (
    <View>
      <Svg width={200} height={200}>
        <Ring pct={{{move_pct}}} r={80} color="#fa114f" />
        <Ring pct={{{exercise_pct}}} r={62} color="#a4f439" />
        <Ring pct={{{stand_pct}}} r={44} color="#1cd8ed" />
      </Svg>
    </View>
  );
}
